#!/usr/bin/env bash
# BancoXYZ S9 - FIX de pagos, transferencias y depositos (sin borrados).
# Ejecutar con BASH desde la raiz del proyecto, tambien desde shell Fish.
set -Eeuo pipefail
export LC_ALL=C

case "${1:---todo}" in
  --todo|--solo-instalar|--limpiar-target) MODO="${1:---todo}" ;;
  *) echo "Uso: bash Semana\ 9/scripts/corregir_pagos_s9.sh [--todo|--solo-instalar|--limpiar-target]" >&2; exit 2;;
esac

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
if [[ -d "$PWD/Semana 9/pagos-service" && -f "$PWD/pom.xml" ]]; then
  RAIZ="$PWD"
else
  RAIZ="$(cd -- "$SCRIPT_DIR/../.." && pwd -P)"
fi
cd "$RAIZ"
[[ -f 'Semana 9/pagos-service/pom.xml' ]] || { echo 'ERROR: Proyecto BancoXYZ S9 no encontrado.' >&2; exit 2; }

limpiar_target() {
  local n=0 d
  while IFS= read -r -d '' d; do
    [[ -f "$(dirname "$d")/pom.xml" ]] || continue
    rm -rf -- "$d"
    echo "TARGET LIMPIADO: ${d#./}"
    n=$((n+1))
  done < <(find 'Semana 9' -type d -name target -prune -print0)
  echo "OK: $n targets Maven eliminados. Ningun CSV/SQL/BD/volumen fue eliminado."
}
if [[ "$MODO" == --limpiar-target ]]; then limpiar_target; exit 0; fi

for p in python3 java mvn; do
 command -v "$p" >/dev/null || { echo "ERROR: falta $p" >&2; exit 2; }
done

# Integridad de fuentes ANTES y DESPUES: nunca modifica los CSV.
CSV_DIR='Semana 9/batch-service/src/main/resources/data'
for csv in movimientos_financieros_diarios.csv intereses_trimestrales.csv estados_financieros_anuales.csv; do
  [[ -f "$CSV_DIR/$csv" ]] || { echo "ERROR: falta CSV $csv" >&2; exit 2; }
done
CSV_SHA_ANTES="$(sha256sum "$CSV_DIR"/*.csv)"

echo '== 1/5 Instalando las clases, pruebas y SQL sin alterar datos existentes =='
python3 - "$RAIZ" <<'PYPAY'
from pathlib import Path
from base64 import b64decode
from hashlib import sha256
import os,sys,tempfile
root=Path(sys.argv[1]).resolve()
files={'Semana 9/data/db/04_pagos_operaciones.sql': '', 'Semana 9/pagos-service/PAGOS_OPERACIONES.md': '', 'Semana 9/pagos-service/src/main/java/cl/duoc/bancoxyz/pagos/PagosController.java': '', 'Semana 9/pagos-service/src/main/java/cl/duoc/bancoxyz/pagos/PagosService.java': '', 'Semana 9/pagos-service/src/main/java/cl/duoc/bancoxyz/pagos/SecurityConfig.java': '', 'Semana 9/pagos-service/src/main/resources/schema.sql': '', 'Semana 9/pagos-service/src/test/java/cl/duoc/bancoxyz/pagos/PagosServiceTest.java': ''}
allowed={'Semana 9/pagos-service/src/main/java/cl/duoc/bancoxyz/pagos/PagosController.java': '11da2644e4174bfdef4f70d86f2a7aa835fec910ff5d2e7dbf1d172d68617267', 'Semana 9/pagos-service/src/main/java/cl/duoc/bancoxyz/pagos/SecurityConfig.java': '1e3e6d0f67c0da22a6b5f720a8ed5ac850d387bedde3466fc2dcc2825ffb7b12', 'Semana 9/pagos-service/src/main/resources/schema.sql': '3c1614286878d78d0b07599d6ceb118a4de74970e411824008308c377887b9ad'}
if not (root/'Semana 9/pagos-service/pom.xml').is_file():
    raise SystemExit('ERROR: No se encontro el modulo pagos-service de Semana 9')
# PREVUELO: ningun archivo existente del usuario se sobreescribe si no es el original conocido.
for name,b64 in files.items():
    target=root/name
    content=b64decode(b64)
    if target.is_symlink(): raise SystemExit('ERROR: Enlace simbolico inesperado: '+name)
    if target.exists():
        previous=sha256(target.read_bytes()).hexdigest()
        desired=sha256(content).hexdigest()
        if previous != desired and previous != allowed.get(name):
            raise SystemExit('ERROR: Archivo distinto del ZIP auditado; se conserva intacto: '+name)
# VALIDAR TODAS las entradas antes de escribir la primera.
for name,b64 in files.items():
    target=root/name
    content=b64decode(b64)
    target.parent.mkdir(parents=True,exist_ok=True)
    if target.exists() and target.read_bytes()==content:
        print('SIN CAMBIOS:',name)
        continue
    fd,tmp=tempfile.mkstemp(prefix='.pagos_tmp_',dir=target.parent)
    try:
        with os.fdopen(fd,'wb') as out:out.write(content)
        os.chmod(tmp,0o644)
        os.replace(tmp,target)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
    print('APLICADO:',name)
print('OK:  Servicio de pagos instalado. CSV, cuentas_intereses y bases existentes intactos.')

PYPAY

[[ "$CSV_SHA_ANTES" == "$(sha256sum "$CSV_DIR"/*.csv)" ]] || {
  echo 'ERROR: los SHA256 de los CSV cambiaron.' >&2; exit 9;
}

if [[ "$MODO" == --solo-instalar ]]; then
 echo 'OK: Codigo instalado. Para probar y desplegar: repetir con --todo'
 exit 0
fi

echo '== 2/5 Compilando pagos-service y ejecutando pruebas JUnit =='
# Validacion ANTES de modificar el esquema o reiniciar el servicio.
mvn -B -f 'Semana 9/pagos-service/pom.xml' clean test

echo '== 3/5 Validando Docker y migrando el esquema de forma aditiva =='
command -v docker >/dev/null || { echo 'ERROR: Docker no disponible; codigo + pruebas OK, migracion PENDIENTE.' >&2; exit 3; }
docker compose config --quiet
BASE="$(docker compose exec -T postgres sh -c 'printf %s "$POSTGRES_DB"')"
[[ "$BASE" == 'bancoxyz' ]] || { echo 'ERROR: se esperaba la unica base bancoxyz; no aplicare DDL.' >&2; exit 3; }
# psql aborta en el primer error SQL. No hay DROP TABLE/DATABASE ni TRUNCATE.
docker compose exec -T postgres sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB" -f -' \
  < 'Semana 9/data/db/04_pagos_operaciones.sql'

echo '== 4/5 Verificando migracion antes de reconstruir SOLO pagos-service =='
ESQUEMA_CONFIRMADO="$(docker compose exec -T postgres sh -c 'psql -X -v ON_ERROR_STOP=1 -At -U "$POSTGRES_USER" -d "$POSTGRES_DB" -f -' <<'SQLCHECK'
SELECT CASE WHEN to_regclass('public.pagos_saldos') IS NOT NULL
                 AND to_regclass('public.pagos_movimientos') IS NOT NULL
                 AND to_regclass('public.pagos_solicitudes') IS NOT NULL
            THEN 'OK' ELSE 'ERROR' END;
SQLCHECK
)"
[[ "$ESQUEMA_CONFIRMADO" == 'OK' ]] || { echo "ERROR: tablas de pagos ausentes: $ESQUEMA_CONFIRMADO" >&2; exit 4; }
# No reinicia PostgreSQL, Keycloak, Kafka ni los otros microservicios.
docker compose up -d --no-deps --build pagos-service

printf 'Verificando health de pagos-service'
LISTO=0
for i in {1..20}; do
  if docker compose exec -T pagos-service sh -c 'curl -fsS http://127.0.0.1:8080/actuator/health >/dev/null' >/dev/null 2>&1; then
    LISTO=1
    break
  fi
  printf '.'
  sleep 3
done
printf '\n'
[[ "$LISTO" == 1 ]] || { echo 'ERROR: Pagos no quedo HEALTHY. Consultar docker compose logs pagos-service' >&2; exit 4; }

[[ "$CSV_SHA_ANTES" == "$(sha256sum "$CSV_DIR"/*.csv)" ]] || {
  echo 'ERROR: integridad CSV no preservada.' >&2; exit 9;
}

echo '== 5/5 Resumen final =='
echo 'OK: PAGO, TRANSFERENCIA y DEPOSITO implementados para cuentas_gestion.'
echo 'OK: Maven, pruebas, SQL aditivo, PostgreSQL y health del servicio.'
echo 'OK: Idempotency-Key, ledger, saldo no negativo y movimientos atomicos.'
echo 'OK: 3 CSV de Semana 9 intactos, Batch separado, sin borrar bases/volumenes/snapshots.'
echo 'AVISO: operaciones HTTP con JWT y cuentas reales de prueba aun requieren prueba E2E autenticada.'
echo 'AVISO: esta es una implementacion de laboratorio, NO bancaria en produccion.'
echo 'RESULTADO PAGOS S9: 0'
